-- FAS graduated fee values transcribed from the original workbook-derived migration.
-- Table 1(a) is represented as CARE_AND_SUPERVISION; Table 1(b) as OTHER_PUBLIC_LAW.
SET search_path TO "${flyway:defaultSchema}";

